update fitness.catalog_releases
   set jcs_sha256 = '2b62b569365dc0f714b9c934ed5a50d1e972468af59cf4fd8868de0567025f7e'
 where version = '1.0.0' and jcs_sha256 = 'ff8d6692617659d8d1f367168e9d1e29cf4d2a103cd9d88e2ac3e6a7e57dcc49';

on conflict (id) do update
  set client_updated_at = excluded.client_updated_at, coeff = excluded.coeff, deleted_at = null
  where (fitness.exercise_stimulus.coeff, fitness.exercise_stimulus.deleted_at) is distinct from (excluded.coeff, null);

-- fitness.exercise_transfer_ratios (30 rows, expert-opinion)
on conflict (from_exercise_id, to_exercise_id) do update
  set ratio = excluded.ratio, evidence = excluded.evidence, catalog_version = excluded.catalog_version
  where (fitness.exercise_transfer_ratios.ratio, fitness.exercise_transfer_ratios.evidence,
         fitness.exercise_transfer_ratios.catalog_version)
        is distinct from (excluded.ratio, excluded.evidence, excluded.catalog_version);

